/**
 * Generate crawlable SEO pages + sitemap from the live public service catalog.
 *
 * Runs:
 *  - automatically before every `npm run build`
 *  - on a schedule from .github/workflows/seo-sync.yml
 *
 * If the catalog API is unreachable, existing generated files are left alone so
 * the site never loses its robots.txt / sitemap / service pages.
 */
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const PUBLIC_DIR = path.join(ROOT, 'frontend', 'public');
const SITE = 'https://fillupo.in';
const API = process.env.SEO_CATALOG_URL || 'https://fillups-in.onrender.com/api/public/services';
const MARKER = '<!-- generated by scripts/generate-seo.mjs -->';

function esc(value) {
  return String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

function titleCase(value) {
  return String(value || '').replace(/(^|[\s-])([a-z])/g, (_, sep, ch) => sep + ch.toUpperCase());
}

function write(file, content) {
  fs.mkdirSync(path.dirname(file), { recursive: true });
  fs.writeFileSync(file, content, 'utf8');
}

async function loadServices() {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), 15000);
  try {
    const response = await fetch(API, {
      headers: { 'user-agent': 'Mozilla/5.0 (compatible; fillupo.in SEO generator)' },
      signal: controller.signal
    });
    if (!response.ok) throw new Error(`catalog HTTP ${response.status}`);
    const data = await response.json();
    const services = Array.isArray(data?.services) ? data.services : [];
    return services.filter(s => /^[a-z0-9-]+$/.test(String(s.slug || '')));
  } finally {
    clearTimeout(timer);
  }
}

function page({ lang, title, description, canonical, enUrl, hiUrl, body, jsonLd }) {
  const ogImage = `${SITE}/og-image.png`;
  return `${MARKER}\n<!doctype html>
<html lang="${lang}">
<head>
<meta charset="utf-8" />
<meta name="viewport" content="width=device-width, initial-scale=1" />
<title>${esc(title)}</title>
<meta name="description" content="${esc(description)}" />
<meta name="robots" content="index, follow, max-image-preview:large" />
<link rel="canonical" href="${esc(canonical)}" />
<link rel="alternate" hreflang="en-IN" href="${esc(enUrl)}" />
<link rel="alternate" hreflang="hi-IN" href="${esc(hiUrl)}" />
<link rel="alternate" hreflang="x-default" href="${esc(enUrl)}" />
<link rel="icon" href="/favicon.ico" sizes="48x48" />
<link rel="icon" type="image/svg+xml" href="/favicon.svg" />
<link rel="icon" type="image/png" sizes="32x32" href="/favicon-32.png" />
<link rel="icon" type="image/png" sizes="16x16" href="/favicon-16.png" />
<link rel="apple-touch-icon" sizes="180x180" href="/apple-touch-icon.png" />
<meta property="og:type" content="website" />
<meta property="og:site_name" content="fillupo.in" />
<meta property="og:title" content="${esc(title)}" />
<meta property="og:description" content="${esc(description)}" />
<meta property="og:url" content="${esc(canonical)}" />
<meta property="og:image" content="${ogImage}" />
<meta property="og:image:width" content="1200" />
<meta property="og:image:height" content="630" />
<meta property="og:image:alt" content="${esc(title)}" />
<meta name="twitter:card" content="summary_large_image" />
<meta name="twitter:title" content="${esc(title)}" />
<meta name="twitter:description" content="${esc(description)}" />
<meta name="twitter:image" content="${ogImage}" />
<script type="application/ld+json">${JSON.stringify(jsonLd).replace(/</g, '\\u003c')}</script>
<style>body{font-family:system-ui,sans-serif;max-width:860px;margin:40px auto;padding:0 20px;color:#0f172a;line-height:1.6}a{color:#0d9488}</style>
</head>
<body>
${body}
<p><a href="${SITE}/">→ Jan Seva services on fillupo.in</a></p>
</body>
</html>
`;
}

function feeText(service) {
  const fees = service.fees || {};
  const total = fees.totalMin ?? fees.total ?? fees.totalMax;
  const govt = fees.govtFeeMin ?? fees.govtFee;
  const serviceFee = fees.serviceFeeMin ?? fees.serviceFee;
  const parts = [];
  if (govt != null) parts.push(`Govt fee ₹${govt}`);
  if (serviceFee != null) parts.push(`Service fee ₹${serviceFee}`);
  if (total != null) parts.push(`Total ₹${total}`);
  return parts.join(' · ') || '—';
}

function servicePage(service, lang) {
  const hi = lang === 'hi';
  const name = titleCase(service.name || service.slug);
  const canonical = hi ? `${SITE}/hi/services/${service.slug}` : `${SITE}/services/${service.slug}`;
  const enUrl = `${SITE}/services/${service.slug}`;
  const hiUrl = `${SITE}/hi/services/${service.slug}`;
  const description = String(service.description || `${name} online application on fillupo.in.`).slice(0, 155);
  const requirements = Array.isArray(service.requirements) ? service.requirements : [];
  const total = service.fees?.totalMin ?? service.fees?.total ?? '0';
  const body = `<h1>${esc(service.icon || '📝')} ${esc(name)}</h1>
<p>${esc(service.description || '')}</p>
<h2>${hi ? 'ज़रूरी दस्तावेज़' : 'Required documents'}</h2>
<ul>${requirements.map(r => `<li>${esc(r)}</li>`).join('') || '<li>—</li>'}</ul>
<p><strong>${hi ? 'शुल्क' : 'Fees'}:</strong> ${esc(feeText(service))}</p>
<p><strong>${hi ? 'क्षेत्र' : 'Scope'}:</strong> ${esc(service.scope || 'online_form')}</p>
<p><a href="${SITE}/${hi ? 'hi/' : ''}services">← ${hi ? 'सभी सेवाएँ' : 'All services'}</a></p>`;
  return page({
    lang,
    title: `${name} — ${hi ? 'शुल्क और ऑनलाइन आवेदन' : 'Fees & Online Application'} | fillupo.in`,
    description,
    canonical,
    enUrl,
    hiUrl,
    body,
    jsonLd: {
      '@context': 'https://schema.org',
      '@type': 'Service',
      name,
      description: service.description || name,
      url: enUrl,
      provider: { '@type': 'Organization', name: 'fillupo.in', url: SITE },
      offers: { '@type': 'Offer', price: String(total), priceCurrency: 'INR' }
    }
  });
}

function indexPage(services, lang) {
  const hi = lang === 'hi';
  const canonical = hi ? `${SITE}/hi/services` : `${SITE}/services`;
  const enUrl = `${SITE}/services`;
  const hiUrl = `${SITE}/hi/services`;
  const heading = hi ? 'सभी सरकारी सेवाएँ और फ़ॉर्म' : 'All government services & online forms';
  const description = hi
    ? 'fillupo.in पर विश्वसनीय जन सेवा ऑपरेटरों के साथ ऑनलाइन फ़ॉर्म और सरकारी सेवाएँ।'
    : 'Find government services, online forms, required documents and verified Jan Seva operators on fillupo.in.';
  const links = services.map(s => {
    const label = titleCase(s.name || s.slug);
    const href = `${SITE}/${hi ? 'hi/' : ''}services/${s.slug}`;
    return `<li><a href="${href}">${esc(s.icon || '📝')} ${esc(label)}</a></li>`;
  }).join('\n');
  const body = `<h1>${esc(heading)}</h1>\n<p>${esc(description)}</p>\n<ul>\n${links}\n</ul>`;
  return page({
    lang,
    title: `${heading} | fillupo.in`,
    description,
    canonical,
    enUrl,
    hiUrl,
    body,
    jsonLd: {
      '@context': 'https://schema.org',
      '@type': 'CollectionPage',
      name: heading,
      url: canonical,
      provider: { '@type': 'Organization', name: 'fillupo.in', url: SITE }
    }
  });
}

function sitemap(services) {
  const urls = [
    `${SITE}/`,
    `${SITE}/services`,
    `${SITE}/hi/services`,
    ...services.flatMap(s => [
      `${SITE}/services/${s.slug}`,
      `${SITE}/hi/services/${s.slug}`
    ])
  ];
  return `<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n${urls.map(u => `  <url><loc>${esc(u)}</loc><changefreq>weekly</changefreq></url>`).join('\n')}\n</urlset>\n`;
}

function removeStale(services) {
  const keep = new Set(services.map(s => s.slug));
  for (const lang of ['', 'hi']) {
    const dir = path.join(PUBLIC_DIR, lang, 'services');
    if (!fs.existsSync(dir)) continue;
    for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
      if (!entry.isDirectory() || keep.has(entry.name)) continue;
      const file = path.join(dir, entry.name, 'index.html');
      if (fs.existsSync(file) && fs.readFileSync(file, 'utf8').startsWith(MARKER)) {
        fs.rmSync(path.join(dir, entry.name), { recursive: true, force: true });
        console.log(`[seo] removed stale page: ${lang}/${entry.name}`);
      }
    }
  }
}

let services = [];
try {
  services = await loadServices();
  if (!services.length) throw new Error('catalog returned no services');
  console.log(`[seo] catalog: ${services.length} services`);
} catch (error) {
  console.warn(`[seo] catalog unavailable (${error.message}) — keeping existing generated files`);
  process.exit(0);
}

write(path.join(PUBLIC_DIR, 'robots.txt'), [
  'User-agent: *',
  'Allow: /',
  'Disallow: /api/',
  'Disallow: /login',
  'Disallow: /order/',
  'Disallow: /admin',
  'Disallow: /dashboard',
  '',
  `Sitemap: ${SITE}/sitemap.xml`,
  ''
].join('\n'));
write(path.join(PUBLIC_DIR, 'sitemap.xml'), sitemap(services));
write(path.join(PUBLIC_DIR, 'services', 'index.html'), indexPage(services, 'en'));
write(path.join(PUBLIC_DIR, 'hi', 'services', 'index.html'), indexPage(services, 'hi'));
for (const service of services) {
  write(path.join(PUBLIC_DIR, 'services', service.slug, 'index.html'), servicePage(service, 'en'));
  write(path.join(PUBLIC_DIR, 'hi', 'services', service.slug, 'index.html'), servicePage(service, 'hi'));
}
removeStale(services);
console.log('[seo] generated robots.txt, sitemap.xml and service pages');
